        if color==bg: continue
        if r in (0,h-1) or c in (0,w-1): continue
        # A marker emits toward the nearest non-background pixel on its row/column.
        candidates=[]
        for cc in range(c-1,-1,-1):
          if grid[r][cc]!=bg: candidates.append((c-cc,'h',cc));break
        for cc in range(c+1,w):
          if grid[r][cc]!=bg: candidates.append((cc-c,'h',cc));break
        for rr in range(r-1,-1,-1):
          if grid[rr][c]!=bg: candidates.append((r-rr,'v',rr));break
        for rr in range(r+1,h):
          if grid[rr][c]!=bg: candidates.append((rr-r,'v',rr));break
        if not candidates: continue
        _,axis,end=min(candidates)
        if axis=='h':
          step=1 if end>c else -1
          for cc in range(c+step,end,step):
            if grid[r][cc]==bg: out[r][cc]=color
        else:
          step=1 if end>r else -1
          for rr in range(r+step,end,step):
            if grid[rr][c]==bg: out[rr][c]=color
        out[r][c]=4
    return out
